entrypoints.signature:
validateBundle(
	value: unknown,
): value is AnalyzeContextBundle

runWithSamplerContext(
	sampler:    SamplingCallback,
	modelHints: readonly string[],
	fn:         () => Promise<T>,
): Promise<T>

runWithClientProviderContext(
	kind: AnalyzeShaperProviderKind,
	fn:   () => Promise<T>,
): Promise<T>

resolveShaperKind(inputs: {
	readonly repoOverride:   AnalyzeShaperProviderKind | undefined;
	readonly globalExplicit: AnalyzeShaperProviderKind | undefined;
	readonly clientDefault:  AnalyzeShaperProviderKind | undefined;
	/** Optional HIGHEST-priority signal (S003 RoleRouter): the tier-resolved
	 *  runner. When present and a valid union member it wins over every other
	 *  signal; a non-union value is coerced to `undefined` so it falls through
	 *  the chain to the `?? 'ollama'` floor (no direct-REST path can slip in). */
	readonly roleResolved?:  AnalyzeShaperProviderKind | undefined;
}): AnalyzeShaperProviderKind

runCapabilityReuseCheck(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The model that judges the candidates; a test passes a stand-in. */
	narrowProvider?: LLMProvider,
): Promise<CapabilityReuseCheckOutput>

graphCompleteness(args: {
	readonly returned:  number;
	readonly found?:    number | null | undefined;
	readonly limited?:  readonly ReachedLimit[] | undefined;
	readonly skipped?:  readonly SkippedItem[] | undefined;
	readonly partlyRead?: readonly PartlyReadItem[] | undefined;
	/** A rule of this lookup that bounds what it looks at, added to the basis note. */
	readonly rule?:     string | undefined;
}): Completeness

runDbConnectionsList(
	_exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The connection pool's source; a test passes a stand-in. */
	acquire: typeof acquirePool = acquirePool,
): Promise<DbConnectionsListOutput>

runDbTableDescribe(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The connection pool's source; a test passes a stand-in. */
	acquire: typeof acquirePool = acquirePool,
): Promise<DbTableDescribeOutput>

runDbTablesList(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The connection pool's source; a test passes a stand-in. */
	acquire: typeof acquirePool = acquirePool,
): Promise<DbTablesListOutput>

stepPlan(
	args: ExecutePlanArgs & {
		readonly resumeState?: StepPlanResumeState;
	},
): Promise<StepPlanResult>

runFreeformProbe(
	exp:  Exploration,
	ctx:  ExplorationRunnerContext,
	/** The tool loop; a test passes a stand-in. */
	loop: typeof runShaperToolLoop = runShaperToolLoop,
): Promise<FreeformProbeOutput>

concludeRun(
	tree:          PlanTreeNode,
	executed:      ExecutorResult,
	contextReport: AnswerReport | undefined,
): { readonly report: AnswerReport; readonly finalReport: unknown }

completeRun(args: {
	readonly record:        RunRecord;
	readonly intent:        ClassifiedIntent;
	readonly tree:          PlanTreeNode;
	readonly executed:      ExecutorResult;
	/** The report of the run context, the run's first step. */
	readonly contextReport: AnswerReport | undefined;
	/** When the run started, in milliseconds. */
	readonly start:         number;
}): RunAnalyzeResult

purgeRun(
	runId: string,
	opts:  {
		readonly force?: boolean;
		/** Says whether a run is live. Only a caller in the process that starts
		 *  the runs can know; one that cannot passes nothing, and an
		 *  'in-progress' record is then refused. */
		readonly isLive?: ((runId: string) => boolean) | undefined;
	} = {},
): PurgeRunResult | PurgeRunRefused

fileWalkCompleteness(
	returned:  number,
	truncated: boolean,
	extra: {
		readonly limited?: readonly ReachedLimit[] | undefined;
		readonly skipped?: readonly SkippedItem[] | undefined;
		readonly cap?:     number | undefined;
	} = {},
): Completeness
